$iterator = new RecursiveIteratorIterator(
    new RecursiveDirectoryIterator($views, RecursiveDirectoryIterator::SKIP_DOTS)
);

$patched = 0;
foreach ($iterator as $file) {
    if ($file->getExtension() !== 'php') {
        continue;
    }
    $path = $file->getPathname();
    if (!str_ends_with($path, '.blade.php')) {
        continue;
    }
    $content = file_get_contents($path);
    $original = $content;
    foreach ($replacements as $from => $to) {
        $content = str_replace($from, $to, $content);
    }
    if ($content !== $original) {
        file_put_contents($path, $content);
        $patched++;
        echo "Patched: " . str_replace($base . DIRECTORY_SEPARATOR, '', $path) . PHP_EOL;
    }
}

// Navbar locale labels
$navbar = $base . '/resources/views/partials/navbar.blade.php';
$navContent = file_get_contents($navbar);
$navReplacements = [
    '<span>🇬🇧</span> English' => '<span>🇬🇧</span> {{ __(\'admin.locale_english\') }}',
    '<span>🇮🇳</span> हिंदी' => '<span>🇮🇳</span> {{ __(\'admin.locale_hindi\') }}',
    '<span>🇮🇳</span> ગુજરાતી' => '<span>🇮🇳</span> {{ __(\'admin.locale_gujarati\') }}',
];
foreach ($navReplacements as $from => $to) {
    $navContent = str_replace($from, $to, $navContent);
}
file_put_contents($navbar, $navContent);
echo "Patched navbar" . PHP_EOL;

echo "Done. {$patched} blade files updated." . PHP_EOL;
